//! Known-answer tests against official, independently-computed test vectors for
//! ML-DSA-65 (Wycheproof, <https://github.com/C2SP/wycheproof>,
//! `testvectors_v1/mldsa_65_verify_test.json`) and SLH-DSA-SHAKE-192f (NIST's own
//! ACVP-Server sample vectors, <https://github.com/usnistgov/ACVP-Server>,
//! `gen-val/json-files/SLH-DSA-{sigVer,sigGen}-FIPS205/internalProjection.json`),
//! run through pqfile's own public `sign::verify_bytes` call site. Unlike a
//! sign-then-verify roundtrip test, the expected result here comes from an
//! independent reference implementation, so a bug that is wrong the same way on
//! both the sign and verify side can't hide. Only a small sample is vendored
//! inline, not a full corpus copy. All vectors use an empty/absent context string,
//! since pqfile's `verify_bytes` has no context-string parameter. See
//! docs/ROADMAP.md, "NIST KAT/ACVP test vectors".

use pem::Pem;
use pqfile::sign::verify_bytes;

fn from_hex(s: &str) -> Vec<u8> {
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap())
        .collect()
}

/// PEM tag pqfile's `sign` module uses for an ML-DSA-65 verifying key
/// (`pqfile::sign::VK_TAG`, not exported since it's `pub(crate)`).
const MLDSA_VK_TAG: &str = "ML-DSA-65 VERIFYING KEY";
/// PEM tag for an SLH-DSA-SHAKE-192f verifying key (`pqfile::sign::SLH_VK_TAG`).
const SLH_VK_TAG: &str = "SLH-DSA-SHAKE-192F VERIFYING KEY";

#[test]
fn mldsa65_verify_matches_wycheproof_vectors() {
    let vk_pem = pem::encode(&Pem::new(MLDSA_VK_TAG, from_hex("")));

    // (tcId, msg_hex, sig_hex, expect_valid) from mldsa_65_verify_test.json,
    // testGroups[0] (all four use an empty/absent context).
    let cases: [(u32, &str, &str, bool); 4] = [
        // tcId 1: baseline
        (1, "48656c6c6f20776f726c64", "", true),
        // tcId 2: empty provided context
        (2, "48656c6c6f20776f726c64", "", true),
        // tcId 6: short signature
        (6, "48656c6c6f20776f726c64", "", false),
        // tcId 8: signature with a bit flip in c_tilde
        (8, "48656c6c6f20776f726c64", "", false),
    ];
    for (tc_id, msg_hex, sig_hex, expect_valid) in cases {
        let msg = from_hex(msg_hex);
        let sig = from_hex(sig_hex);
        let result = verify_bytes(&vk_pem, &msg, &sig);
        assert_eq!(
            result.is_ok(),
            expect_valid,
            "tcId {tc_id} unexpected result: {result:?}"
        );
    }
}

#[test]
fn slhdsa_shake_192f_verify_matches_nist_acvp_vectors() {
    // Valid case: NIST ACVP-Server SLH-DSA-sigGen-FIPS205 sample vectors,
    // internalProjection.json, tgId 9 (deterministic, SLH-DSA-SHAKE-192f,
    // external/pure), tcId 81 (empty context) - sourced from sigGen rather
    // than sigVer because no empty-context *valid* case exists in the
    // sigVer sample; a signature the reference implementation itself
    // produced is an equally valid "expected valid" fixture.
    let valid_pk = from_hex("0799AFE38A59127DD8DA27F841224D62507A628349F41C2CFEFD1454A9F2A6E7A6F8DA91179BFC5400BA58CBB3FDE550");
    let valid_msg = from_hex("");
    let valid_sig = from_hex("");
    let valid_vk_pem = pem::encode(&Pem::new(SLH_VK_TAG, valid_pk));
    verify_bytes(&valid_vk_pem, &valid_msg, &valid_sig)
        .expect("NIST-reference-computed signature must verify");

    // Invalid case: NIST ACVP-Server SLH-DSA-sigVer-FIPS205 sample vectors,
    // internalProjection.json, tgId 9, tcId 119 ("modified signature - R", empty context).
    let invalid_pk = from_hex("A5E87D47D9267CACC41C176BA6D06F48FCAC39140812F24632DB57E8340D3066B11239FDD59370C30A55257729DE1A70");
    let invalid_msg = from_hex("");
    let invalid_sig = from_hex("");
    let invalid_vk_pem = pem::encode(&Pem::new(SLH_VK_TAG, invalid_pk));
    assert!(
        verify_bytes(&invalid_vk_pem, &invalid_msg, &invalid_sig).is_err(),
        "tampered reference signature must be rejected"
    );
}
